using System;using System.Linq;using System.Reflection;using System.Threading.Tasks;using UnityEngine;using Codice.Characters;using Codice.Presentation;using Codice.UI;
public static class VerifyNativeGameplay{
 static BindingFlags F=BindingFlags.Instance|BindingFlags.NonPublic;
 static void Check(bool ok,string message){if(!ok)throw new Exception(message);}
 static async Task Wait(float duration){float until=Time.time+duration;for(int i=0;i<150&&Time.time<until;i++)await Task.Delay(30);Check(Time.time>=until,"Simulation paused");}
 static void Ready(PlayerCombat combat){combat.GetType().GetMethod("InterruptCombo",F).Invoke(combat,null);combat.GetType().GetField("nextAttack",F).SetValue(combat,0f);}
 public static async Task<string> Run(){
  if(UnityEngine.SceneManagement.SceneManager.GetActiveScene().name!="Descenso")UnityEngine.SceneManagement.SceneManager.LoadScene("Descenso");for(int i=0;i<100&&(!RunHUD.Instance||!RunHUD.Instance.Player);i++)await Task.Delay(100);await Wait(.4f);
  var p=RunHUD.Instance.Player;RunHUD.Instance.SetPaused(false);p.SetNarrativeControlsBlocked(false);p.State.Initialize(PlayerClass.Warrior);await Wait(.2f);var combat=p.GetComponent<PlayerCombat>();var ap=p.GetComponent<ActorPresentation>();var camera=p.GetComponent<HumanPreviewCamera>();if(!camera.ThirdPerson)camera.Toggle();p.enabled=false;combat.enabled=false;
  var cc=p.GetComponent<CharacterController>();var saved=p.transform.position;var floor=GameObject.CreatePrimitive(PrimitiveType.Cube);floor.transform.position=new Vector3(1700,99.5f,1700);floor.transform.localScale=new Vector3(50,1,50);cc.enabled=false;p.transform.SetPositionAndRotation(new Vector3(1700,100.05f,1700),Quaternion.identity);cc.enabled=true;Physics.SyncTransforms();
  try{
   p.State.EquipIntoSlot(new WeaponInstance(WeaponKind.Sword),0);p.State.EquipIntoSlot(new WeaponInstance(WeaponKind.Axe),1);p.State.SelectWeapon(0);await Wait(.15f);combat.GetType().GetMethod("UpdateWeapon",F).Invoke(combat,new object[]{p.State.ActiveWeapon});
   Check(combat.HasKnightShield,"Knight lacks shield mechanic");Check(ap.Body.GetComponentsInChildren<Transform>().Any(t=>t.name=="Third person left grip"),"Knight shield absent");
   Ready(combat);p.SprintRequested=false;for(int i=0;i<20;i++)p.SimulateMotor(Vector3.forward,true,1f/60);float walk=p.MotorVelocity.magnitude;ap.Play("Walk");Check(ap.CurrentState=="Walk","Warrior gait still overrides Human walk");Check(Mathf.Abs(walk-3.4f)<.1f,"Walking speed "+walk);
   p.SprintRequested=true;for(int i=0;i<20;i++)p.SimulateMotor(Vector3.forward,true,1f/60);float run=p.MotorVelocity.magnitude;ap.Play("HeavyRun");Check(ap.CurrentState=="Movement","Heavy gait still overrides Human run");Check(Mathf.Abs(run-6)<.1f,"Running speed "+run);p.SprintRequested=false;
   Ready(combat);Check(combat.TryAttack(),"Sword attack rejected");Check(ap.CurrentState=="SwordCombo1","Sword launches two different states");Check(ap.Body.GetFloat("ActionSpeed")<=1.251f,"Native sword overaccelerated");await Wait(.15f);Check(!combat.TryAttack(),"Attack overlaps existing swing");var attackStart=p.transform.position;for(int frame=0;frame<10;frame++)p.SimulateMotor(Vector3.forward,true,1f/60);Check(Vector3.ProjectOnPlane(p.transform.position-attackStart,Vector3.up).magnitude<.001f,"Sword moves while attacking");Check(!p.TryJump(),"Sword allows jump during attack");for(int layer=1;layer<ap.Body.layerCount;layer++)Check(ap.Body.GetLayerWeight(layer)==0,"Action has active mask layer");Check(ap.Body.GetLayerWeight(1)==0,"Mixed offhand still deforms pose");Ready(combat);
   var bow=new WeaponInstance(WeaponKind.Bow);p.State.EquipIntoSlot(bow,0);p.State.SelectWeapon(0);combat.GetType().GetMethod("UpdateWeapon",F).Invoke(combat,new object[]{bow});await Wait(.15f);Ready(combat);Check(combat.TryAttack()&&combat.BowMotionLocked,"Bow failed to lock locomotion");var start=p.transform.position;for(int i=0;i<12;i++)p.SimulateMotor(Vector3.forward,true,1f/60);Check(Vector3.ProjectOnPlane(p.transform.position-start,Vector3.up).magnitude<.01f,"Bow slides while firing");Check(!p.TryJump(),"Bow allows jump during shot");p.GetType().GetField("nextDash",F).SetValue(p,0f);Check(p.TryDash(Vector3.right),"Bow cannot cancel into dodge");Check(!combat.BowMotionLocked&&!combat.IsSwinging,"Dodge did not cancel arrow");p.SimulateMotor(Vector3.right,true,1f/60);Check(p.MotorVelocity.magnitude>4,"Dodge blocked by bow lock");await Wait(.5f);
   var thrown=new WeaponInstance(WeaponKind.Bow){shuriken=true};p.State.EquipIntoSlot(thrown,0);p.State.SelectWeapon(0);combat.GetType().GetMethod("UpdateWeapon",F).Invoke(combat,new object[]{thrown});await Wait(.15f);Ready(combat);Check(camera.HeldWeapon.IsChildOf(ap.Body.GetBoneTransform(HumanBodyBones.RightHand)),"Throwing weapon on wrong hand");Check(combat.TryAttack(),"Throw rejected");Check(ap.CurrentState=="ThrowShuriken","Throwing uses spell clip state");Check(ap.Body.GetFloat("ActionSpeed")<=1.251f,"Throw overaccelerated");
   string result=$"PASS Human walk {walk:F2}m/s run {run:F2}m/s; sword+shield; one sword state; native speed <=1.25; no offhand overlay; bow stationary, no jump, dodge cancels; right-hand native throw";Debug.Log(result);return result;
  }finally{Ready(combat);p.SprintRequested=false;cc.enabled=false;p.transform.position=saved;cc.enabled=true;p.enabled=true;combat.enabled=true;UnityEngine.Object.Destroy(floor);}
 }
}

